import sys
import types
import functools

try:
    import six  # noqa: F401
except ImportError:
    _six = types.ModuleType("six")
    _six.wraps = functools.wraps

    def _reraise(tp, value, tb=None):
        if value is None:
            value = tp()
        if value.__traceback__ is not tb:
            raise value.with_traceback(tb)
        raise value

    _six.reraise = _reraise
    sys.modules["six"] = _six

import pytest

import retrying
from retrying import retry, Retrying, RetryError, Attempt


class FakeTime(object):
    """Fake clock: sleep advances time instead of blocking."""

    def __init__(self):
        self.now = 1000.0
        self.sleeps = []

    def time(self):
        return self.now

    def sleep(self, s):
        self.sleeps.append(s)
        self.now += s


@pytest.fixture
def clock(monkeypatch):
    fake = FakeTime()
    monkeypatch.setattr(retrying, "time", fake)
    return fake


class Flaky(object):
    def __init__(self, fail_times, exc=IOError, result="ok"):
        self.fail_times = fail_times
        self.exc = exc
        self.result = result
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        if self.calls <= self.fail_times:
            raise self.exc("fail")
        return self.result


def test_simple_decorator_retries_until_success(clock):
    f = Flaky(10)

    @retry
    def g():
        return f()

    assert g() == "ok"
    assert f.calls == 11


