import io
from collections import OrderedDict

import pytest

import xmltodict


def test_parse_readme_example():
    doc = xmltodict.parse("""
    <mydocument has="an attribute">
      <and>
        <many>elements</many>
        <many>more elements</many>
      </and>
      <plus a="complex">
        element as well
      </plus>
    </mydocument>
    """)
    assert doc == {
        "mydocument": {
            "@has": "an attribute",
            "and": {"many": ["elements", "more elements"]},
            "plus": {"@a": "complex", "#text": "element as well"},
        }
    }


NS_XML = """
<root xmlns="http://defaultns.com/"
      xmlns:a="http://a.com/"
      xmlns:b="http://b.com/">
  <x>1</x>
  <a:y>2</a:y>
  <b:z>3</b:z>
</root>
"""


def _without_xmlns(d):
    # Compare only the namespace-expanded element content; the declaration
    # attribute handling is not asserted here.
    assert len(d) == 1
    (rootkey, rootval), = d.items()
    rootval = {k: v for k, v in rootval.items() if k != '@xmlns'}
    return {rootkey: rootval}


def test_process_namespaces():
    result = xmltodict.parse(NS_XML, process_namespaces=True)
    assert _without_xmlns(result) == {
        'http://defaultns.com/:root': {
            'http://defaultns.com/:x': '1',
            'http://a.com/:y': '2',
            'http://b.com/:z': '3',
        }
    }


def test_namespace_collapse_and_skip():
    namespaces = {
        'http://defaultns.com/': None,
        'http://a.com/': 'ns_a',
    }
    result = xmltodict.parse(NS_XML, process_namespaces=True,
                             namespaces=namespaces)
    assert _without_xmlns(result) == {
        'root': {
            'x': '1',
            'ns_a:y': '2',
            'http://b.com/:z': '3',
        }
    }


def test_namespaces_not_processed_by_default():
    d = xmltodict.parse('<a xmlns:x="http://x/"><x:b>1</x:b></a>')
    assert d == {'a': {'@xmlns:x': 'http://x/', 'x:b': '1'}}


def test_force_cdata_tuple():
    xml = '<a><b>data1</b><c>data2</c><d>data3</d></a>'
    assert xmltodict.parse(xml, force_cdata=('b', 'd')) == {
        'a': {'b': {'#text': 'data1'}, 'c': 'data2', 'd': {'#text': 'data3'}}}


def test_force_cdata_true():
    xml = '<a><b>data1</b><c>data2</c><d>data3</d></a>'
    assert xmltodict.parse(xml, force_cdata=True) == {
        'a': {'b': {'#text': 'data1'}, 'c': {'#text': 'data2'},
              'd': {'#text': 'data3'}}}


def test_force_cdata_callable():
    xml = '<a><b>data1</b><c>data2</c><d>data3</d></a>'

    def should(path, key, value):
        return key in ['b', 'd'] and len(value) > 4

    assert xmltodict.parse(xml, force_cdata=should) == {
        'a': {'b': {'#text': 'data1'}, 'c': 'data2', 'd': {'#text': 'data3'}}}


def test_force_list_tuple():
    xml = '<a><b>data1</b><b>data2</b><c>data3</c></a>'
