        return None if key == "@x" else (key, value)

    assert xmltodict.parse('<a x="1" y="2">t</a>', postprocessor=pp) == {
        "a": {"@y": "2", "#text": "t"}}


# ---- unparse ----

def test_unparse_bool_values():
    assert xmltodict.unparse({"a": True}, full_document=False) == "<a>true</a>"
    assert xmltodict.unparse({"a": False}, full_document=False) == "<a>false</a>"
    assert xmltodict.unparse({"a": {"@x": True}},
                             full_document=False) == '<a x="true"></a>'


def test_unparse_int_and_bytes_values():
    assert xmltodict.unparse({"a": 1}, full_document=False) == "<a>1</a>"
    assert xmltodict.unparse({"a": b"hi"}, full_document=False) == "<a>hi</a>"


def test_unparse_none_attribute_and_none_cdata():
    assert xmltodict.unparse({"a": {"@x": None}},
                             full_document=False) == '<a x=""></a>'
    assert xmltodict.unparse({"a": {"@x": "1", "#text": None}},
                             full_document=False) == '<a x="1"></a>'


