    with pytest.raises(ValueError):
        xmltodict.unparse({name: "x"}, full_document=False)


def test_unparse_non_string_element_name():
    with pytest.raises(ValueError):
        xmltodict.unparse({1: "x"}, full_document=False)


@pytest.mark.parametrize("attr", ["@x y", "@x=y", "@x<y", "@x/y", '@x"y'])
def test_unparse_invalid_attribute_names(attr):
    with pytest.raises(ValueError):
        xmltodict.unparse({"a": {attr: "1"}}, full_document=False)


def test_unparse_xmlns_dict():
