def test_nested_namespace_declarations_reset_between_elements():
    xml = '<a xmlns:n="u"><b xmlns:m="v"/></a>'
    result = xmltodict.parse(xml, process_namespaces=True)
    assert result == {
        "a": {
            "@xmlns": {"n": "u"},
            "b": {"@xmlns": {"m": "v"}},
        }
    }


def test_sibling_namespace_declarations_not_accumulated():
    xml = '<a><b xmlns:m="v"/><c xmlns:n="w"/></a>'
    result = xmltodict.parse(xml, process_namespaces=True)
    assert result == {
        "a": {
            "b": {"@xmlns": {"m": "v"}},
            "c": {"@xmlns": {"n": "w"}},
        }
    }


def test_streaming_empty_element_yields_none():
    items = []

    def cb(path, item):
        items.append(item)
        return True

    xmltodict.parse("<a>\n <b>1</b>\n <b/>\n <b></b>\n</a>",
                    item_depth=2, item_callback=cb)
    assert items == ["1", None, None]


def test_streaming_whitespace_only_element_yields_none():
    items = []

    def cb(path, item):
        items.append(item)
        return True

    xmltodict.parse("<a><b>   </b></a>", item_depth=2, item_callback=cb)
    assert items == [None]


def test_comment_after_sibling_preserves_existing_children():
    assert xmltodict.parse("<a><b>1</b><!-- c --></a>",
                           process_comments=True) == {
        "a": {"b": "1", "#comment": "c"}}


def test_comment_preserves_attributes():
    assert xmltodict.parse('<a x="1"><!--c--></a>',
                           process_comments=True) == {
        "a": {"@x": "1", "#comment": "c"}}


def test_comment_between_children_keeps_all():
    assert xmltodict.parse("<a><b>1</b><!--c--><d>2</d></a>",
                           process_comments=True) == {
        "a": {"b": "1", "#comment": "c", "d": "2"}}


def test_postprocessor_receives_path_list():
    calls = []

    def pp(path, key, value):
        calls.append(([name for name, _ in path], key, value))
        return key, value

    xmltodict.parse("<a><b>1</b></a>", postprocessor=pp)
    assert calls == [
        (["a", "b"], "b", "1"),
        (["a"], "a", {"b": "1"}),
    ]


def test_postprocessor_path_includes_attributes_of_ancestors():
    seen = []

    def pp(path, key, value):
        seen.append((list(path), key))
        return key, value

    xmltodict.parse('<a x="1"><b>2</b></a>', postprocessor=pp)
    assert seen[0] == ([("a", {"x": "1"})], "@x")
    assert seen[1] == ([("a", {"x": "1"}), ("b", None)], "b")


def test_streaming_item_depth_one_receives_root_dict():
    items = []

    def cb(path, item):
        items.append(([name for name, _ in path], item))
        return True

    result = xmltodict.parse("<a><b>1</b><c>2</c></a>", item_depth=1,
                             item_callback=cb)
    assert result is None
    assert items == [(["a"], {"b": "1", "c": "2"})]


def test_streaming_item_with_attributes_and_text():
