def test_force_list_callable_single_element_gets_value():
    def f(path, key, value):
        return key == "b" and isinstance(value, str)

    assert xmltodict.parse("<a><b>1</b></a>", force_list=f) == {
        "a": {"b": ["1"]}}


def test_force_list_callable_receives_value_and_path():
    calls = []

    def f(path, key, value):
        calls.append((list(path), key, value))
        return False

    xmltodict.parse("<a><b>1</b></a>", force_list=f)
    assert calls == [
        ([("a", None)], "b", "1"),
        ([], "a", {"b": "1"}),
    ]


def test_force_list_callable_path_includes_parent_attributes():
