    def f(path, key, value):
        calls.append((list(path), key))
        return False

    xmltodict.parse('<a x="1"><b>1</b></a>', force_list=f)
    assert calls[0] == ([("a", {"x": "1"})], "b")


def test_force_cdata_callable_receives_path_key_value():
