def test_streaming_force_cdata_callable_path():
    calls = []
    items = []

    def f(path, key, value):
        calls.append(([n for n, _ in path], key, value))
        return True

    def cb(path, item):
        items.append(item)
        return True

    xmltodict.parse("<a><b><c>x</c></b></a>", item_depth=3,
                    item_callback=cb, force_cdata=f)
    assert calls == [(["a", "b"], "c", "x")]
    assert items == [{"#text": "x"}]


