def test_custom_separator_with_namespace_mapping():
    result = xmltodict.parse('<a xmlns="u"><b>1</b></a>',
                             process_namespaces=True,
                             namespace_separator="|",
                             namespaces={"u": "x"})
    assert result == {"x|a": {"@xmlns": {"": "u"}, "x|b": "1"}}


