import xmltodict


def test_handler_initial_data_is_list_after_element_roundtrip():
    h = xmltodict._DictSAXHandler()
    h.startElement("a", {})
    h.endElement("a")
    assert h.data == []
    assert h.item == {"a": None}


def test_handler_accepts_dict_attrs_directly():
    h = xmltodict._DictSAXHandler()
    h.startElement("a", {"x": "1"})
    h.characters("t")
    h.endElement("a")
    assert h.item == {"a": {"@x": "1", "#text": "t"}}


def test_handler_streaming_end_with_empty_stack_resets_item_to_none():
    seen = []

    def cb(path, item):
        seen.append(item)
        return True

    h = xmltodict._DictSAXHandler(item_depth=1, item_callback=cb)
    h.path = [("a", None)]
    h.item = {"k": "v"}
    h.data = []
    h.stack = []
    h.endElement("a")
    assert seen == [{"k": "v"}]
    assert h.item is None
    assert h.data == []
    assert h.path == []


def test_parse_str_input_uses_utf8_encoding_name():
    calls = []

    class FakeParser:
        def Parse(self, data, final):
            self.data = data

        def ParseFile(self, f):
            pass

    class FakeExpat:
        def ParserCreate(self, encoding, sep):
            calls.append((encoding, sep))
            return FakeParser()

    result = xmltodict.parse("<a>1</a>", expat=FakeExpat())
    assert result is None
    assert calls == [("utf-8", None)]


def test_convert_value_to_string_default_encoding_bytes():
    assert xmltodict._convert_value_to_string(b"hi") == "hi"
    assert xmltodict._convert_value_to_string(bytearray(b"yo")) == "yo"


import xmltodict
import pytest


def test_handler_data_reset_to_empty_list_below_item_depth():
    h = xmltodict._DictSAXHandler(item_depth=2)
    h.startElement("a", {})
    h.endElement("a")
    assert h.data == []
    assert h.item is None
    assert h.path == []


def test_parse_sets_ordered_attributes_true():
    created = []

    class FakeParser:
        def Parse(self, data, final):
            pass

        def ParseFile(self, f):
            pass

    class FakeExpat:
        def ParserCreate(self, encoding, sep):
            p = FakeParser()
            created.append(p)
            return p

    xmltodict.parse("<a>1</a>", expat=FakeExpat())
    assert created[0].ordered_attributes is True


def test_validate_comment_decodes_bytes():
    assert xmltodict._validate_comment(b"hi") == "hi"
    assert xmltodict._validate_comment("hi") == "hi"


def test_validate_comment_invalid_utf8_bytes_raises():
